WITH flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM web_events), sessions_web_events AS (SELECT id, session_id, event_time, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('WEEK', event_time) AS week_start, CASE WHEN island_id >= 9 THEN 'LARGE' ELSE 'SMALL' END AS island_id_tier, ROUND(AVG(island_id), 2) AS avg_island_id, MIN(event_time) AS first_seen, COUNT(*) AS row_count, COUNT(*) AS row_count_2 FROM sessions_web_events GROUP BY DATE_TRUNC('WEEK', event_time), CASE WHEN island_id >= 9 THEN 'LARGE' ELSE 'SMALL' END ORDER BY avg_island_id DESC;
